package com.smartcoffee.modules.inventory.application;import com.smartcoffee.modules.inventory.api.InventoryBalanceResponse;import com.smartcoffee.modules.inventory.persistence.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class InventoryQueryService{private final InventoryBalanceRepository balances;private final IngredientRepository ingredients;private final UnitOfMeasureRepository units;public InventoryQueryService(InventoryBalanceRepository b,IngredientRepository i,UnitOfMeasureRepository u){balances=b;ingredients=i;units=u;}@Transactional(readOnly=true)public List<InventoryBalanceResponse>list(UUID store){return balances.byStore(store).stream().map(b->{var i=ingredients.findById(b.id().ingredientId()).orElseThrow();var u=units.findById(i.baseUnitId()).orElseThrow();return new InventoryBalanceResponse(i.id(),i.code(),i.name(),u.code(),b.currentStock(),b.reservedStock(),b.availableStock(),b.minimumStock(),b.averageUnitCost(),b.availableStock().compareTo(b.minimumStock())<=0,b.version());}).toList();}}

